void transcriptionFixture(const File& file){file.getParentDirectory().createDirectory();file.deleteFile();AudioBuffer<float> audio(2,86400);audio.clear();int pitches[]={60,64,67};double starts[]={.2,.75,1.25},ends[]={.6,1.1,1.65};for(int n=0;n<3;++n)for(int i=(int)(starts[n]*48000);i<(int)(ends[n]*48000);++i){double t=i/48000.-starts[n],hz=440*std::pow(2.,(pitches[n]-69)/12.);float v=(float)(.25*jmin(1.,t/.005,(ends[n]-i/48000.)/.005)*std::sin(2*MathConstants<double>::pi*hz*t));audio.setSample(0,i,v);audio.setSample(1,i,-v);}auto stream=file.createOutputStream();WavAudioFormat format;std::unique_ptr<AudioFormatWriter> writer(stream?format.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);if(writer){stream.release();writer->writeFromAudioSampleBuffer(audio,0,audio.getNumSamples());}}
AlertWindow* transcriptionDialog(const String& title){auto* d=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());return d&&d->getName()==title?d:nullptr;}
void closeTranscription(const String& title,int answer){if(auto* d=transcriptionDialog(title))d->exitModalState(answer);}
void transcriptionSnapshot(AlertWindow* d,const File& file){if(!d)return;FileOutputStream stream(file);PNGImageFormat png;png.writeImageToStream(d->createComponentSnapshot(d->getLocalBounds()),stream);}
