void Studio::runTranscriptionChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    auto saved=std::move(project);auto previousFile=currentFile;auto undo=std::move(undoStack),redo=std::move(redoStack);auto oldRevision=revision;bool wasDirty=dirty;int track=selectedTrack;auto oldWave=waveFile;auto* oldSample=waveSample;double a=waveStart,b=waveEnd,view=waveViewStart,span=waveSpan;auto history=std::move(waveHistory),forward=std::move(waveRedoHistory);auto oldOptions=transcriptionOptions;
    perform(stop);cancelNoteTool();discardTranscription();project=emptyProject();project.bpm=120;project.songMode=true;selectedTrack=7;currentFile={};undoStack.clear();redoStack.clear();publish();engine->prepare(48000);auto file=folder.getChildFile("transcription-source.wav");transcriptionFixture(file);auto hash=SHA256(file).toHexString();openWaveform(file);auto sourceProject=JSON::toString(projectToJson(project));auto rev=revision;TranscriptionOptions options;options.bpm=project.bpm;
    auto wait=[&]{auto until=Time::getMillisecondCounter()+15000;while(transcriptionTask&&Time::getMillisecondCounter()<until){finishTranscription();Thread::sleep(2);}return !transcriptionTask;};
    check(beginTranscription(options,7,rev,waveRevision,false)&&wait()&&transcriptionCurrent(),"waveform worker produces a current monophonic note preview");
    check(transcription.notes.size()==3&&transcription.notes[0].note.pitch==60&&transcription.notes[1].note.pitch==64&&transcription.notes[2].note.pitch==67,"native decoded source transcribes exact generated melody pitches");
    check(JSON::toString(projectToJson(project))==sourceProject&&revision==rev&&undoStack.empty(),"analysis and report persistence create no musical edits or Undo entries");
    auto report=root.getChildFile("data/transcription-report.json");auto json=JSON::parse(report);check(json.isObject()&&json["sourceHash"].toString()==hash&&json["notes"].getArray()->size()==3,"saved transcription report retains source hash, timing and note confidence");
    AudioBuffer<float> block(2,32768);check(auditionTranscription(false),"Original audition starts the source selection");getNextAudioBlock(AudioSourceChannelInfo(&block,0,32768));check(engine->previewPlaying.load()&&block.getMagnitude(0,0,32768)>.1f&&!engine->playing.load(),"original selection reaches raw stereo audition without Song playback");
    check(auditionTranscription(true)&&transcriptionNoteAudition&&pendingNoteTool(),"Notes audition publishes a temporary PAT graph and guards pending musical preview");getNextAudioBlock(AudioSourceChannelInfo(&block,0,32768));check(engine->playing.load()&&block.getMagnitude(0,0,32768)>.001f&&JSON::toString(projectToJson(project))==sourceProject&&undoStack.empty(),"temporary notes are audible without adding a pattern or changing music history");
    stopTranscriptionAudition();getNextAudioBlock(AudioSourceChannelInfo(&block,0,32768));check(!transcriptionNoteAudition&&!pendingNoteTool()&&!engine->playing.load()&&JSON::toString(projectToJson(project))==sourceProject,"Stop restores the original playback graph and clears the pending preview guard");
    inputMonitor.store(true);check(!auditionTranscription(true)&&inputMonitor.load(),"input monitoring cannot contaminate Original/Notes comparison");inputMonitor.store(false);
    recording=true;check(!beginTranscription(options,7,rev,waveRevision,false)&&!auditionTranscription(true)&&!applyTranscription(),"active takes guard analysis audition and Apply");recording=false;
    check(applyTranscription()&&project.patterns.size()==2&&!project.songMode&&project.activePattern==1&&lane().size()==3&&selectedNotes.size()==3&&undoStack.size()==1,"explicit Apply creates one new PAT pattern and selects editable melody notes as one Undo");
    perform(undoAction);check(JSON::toString(projectToJson(project))==sourceProject,"one musical Undo restores the full pre-transcription project");perform(redoAction);check(project.patterns.size()==2&&lane().size()==3,"Redo restores the entire generated pattern");
    check(SHA256(file).toHexString()==hash&&waveFile==file&&waveHistory.empty(),"analysis preview Apply and Undo never alter source file or waveform history");
    auto preserved=JSON::toString(projectToJson(project));check(!beginTranscription(options,7,revision-1,waveRevision,false)&&!transcriptionTask,"stale project revision cannot start a transcription");check(!beginTranscription(options,7,revision,waveRevision-1,false),"stale waveform selection cannot start a transcription");
    check(beginTranscription(options,7,revision,waveRevision,false),"cancellable transcription worker starts");discardTranscription();check(wait()&&transcription.notes.empty()&&status.contains("cancelled")&&JSON::toString(projectToJson(project))==preserved,"Cancel discards background results without creating musical history");
    check(beginTranscription(options,7,revision,waveRevision,false),"selection-change fixture starts");++waveRevision;check(wait()&&transcription.notes.empty()&&status.contains("changed"),"changing waveform selection rejects an in-flight analysis result");
    check(beginTranscription(options,7,revision,waveRevision,false)&&wait()&&transcriptionCurrent(),"analysis can be rebuilt after cancellation and selection changes");auto time=file.getLastModificationTime();file.setLastModificationTime(time+RelativeTime::seconds(3));check(!applyTranscription()&&!auditionTranscription(true),"source metadata changes prevent stale Apply or audition");file.setLastModificationTime(time);discardTranscription();
    auto changed=folder.getChildFile("changed-transcription-source.wav");transcriptionFixture(changed);openWaveform(changed);auto oldTime=changed.getLastModificationTime();AudioBuffer<float> different(2,86400);different.clear();changed.deleteFile();auto stream=changed.createOutputStream();WavAudioFormat format;std::unique_ptr<AudioFormatWriter> writer(stream?format.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);if(writer){stream.release();writer->writeFromAudioSampleBuffer(different,0,86400);writer.reset();}changed.setLastModificationTime(oldTime);check(beginTranscription(options,7,revision,waveRevision,false)&&wait()&&transcription.notes.empty()&&status.contains("Reopen"),"worker verifies decoded selection even when external replacement retains file size and timestamp");
    stopTranscriptionAudition();discardTranscription();project=std::move(saved);currentFile=previousFile;undoStack=std::move(undo);redoStack=std::move(redo);revision=oldRevision;dirty=wasDirty;selectedTrack=track;waveFile=oldWave;waveSample=oldSample;waveStart=a;waveEnd=b;waveViewStart=view;waveSpan=span;waveHistory=std::move(history);waveRedoHistory=std::move(forward);transcriptionOptions=oldOptions;++waveRevision;publish();
}
void Studio::runTranscriptionTransportTick(){
    auto put=[&](const char* key,bool ok){transportResults.getDynamicObject()->setProperty(key,ok);};auto source=transportReport.getSiblingFile("native-transcription-source.wav");auto pending=[&]{if(!transcriptionTask)return false;int n=(int)transportResults["transcriptionWait"];if(n>=500)return false;transportResults.getDynamicObject()->setProperty("transcriptionWait",n+1);--transportTicks;return true;};
    if(transportTicks==6800){perform(stop);cancelNoteTool();discardTranscription();project=emptyProject();project.bpm=120;project.songMode=true;selectedTrack=7;currentFile={};undoStack.clear();redoStack.clear();publish();transcriptionFixture(source);transportResults.getDynamicObject()->setProperty("transcriptionSourceHash",SHA256(source).toHexString());openWaveform(source);transcriptionOptions={};showTranscriptionSettings();put("nativeTranscriptionSettings",transcriptionDialog("Audio to notes (monophonic)")!=nullptr);transcriptionSnapshot(transcriptionDialog("Audio to notes (monophonic)"),transportReport.getSiblingFile("native-transcription-settings.png"));if(auto* d=transcriptionDialog("Audio to notes (monophonic)"))d->getComboBoxComponent("track")->setSelectedItemIndex(7);closeTranscription("Audio to notes (monophonic)",1);}
    if(transportTicks==6810){if(pending())return;put("nativeTranscriptionReady",transcriptionCurrent()&&transcription.notes.size()==3&&transcriptionDialog("Audio to notes review"));transcriptionSnapshot(transcriptionDialog("Audio to notes review"),transportReport.getSiblingFile("native-transcription-review.png"));engine->observedPeak.store(0);closeTranscription("Audio to notes review",1);}
    if(transportTicks==6820){put("nativeTranscriptionOriginal",engine->previewPlaying.load()&&engine->observedPeak.load()>.1f&&!engine->playing.load());closeTranscription("Audio to notes review",2);}
    if(transportTicks==6825)engine->observedPeak.store(0);
    if(transportTicks==6830){put("nativeTranscriptionNotes",engine->playing.load()&&transcriptionNoteAudition&&engine->observedPeak.load()>.001f&&project.patterns.size()==1&&undoStack.empty());closeTranscription("Audio to notes review",3);}
    if(transportTicks==6840){put("nativeTranscriptionStop",!engine->playing.load()&&!transcriptionNoteAudition&&!engine->previewPlaying.load()&&project.patterns.size()==1);closeTranscription("Audio to notes review",4);}
    if(transportTicks==6850){put("nativeTranscriptionApply",project.patterns.size()==2&&lane().size()==3&&!project.songMode&&undoStack.size()==1);perform(undoAction);put("nativeTranscriptionUndo",project.patterns.size()==1&&project.songMode);perform(redoAction);put("nativeTranscriptionRedo",project.patterns.size()==2&&lane().size()==3);beginTranscription(TranscriptionOptions{},7,revision,waveRevision,false);++waveRevision;}
    if(transportTicks==6860){if(pending())return;put("nativeTranscriptionStale",transcription.notes.empty()&&status.contains("changed"));beginTranscription(TranscriptionOptions{},7,revision,waveRevision,false);discardTranscription();}
    if(transportTicks==6870){if(pending())return;put("nativeTranscriptionCancel",transcription.notes.empty()&&!transcriptionTask);recording=true;put("nativeTranscriptionRecording",!beginTranscription(TranscriptionOptions{},7,revision,waveRevision,false)&&!applyTranscription());recording=false;put("nativeTranscriptionRetained",SHA256(source).toHexString()==transportResults["transcriptionSourceHash"].toString()&&project.patterns.size()==2&&lane().size()==3);perform(stop);}
}
